// node --test tests/*.test.mjs   — the double-precision core against mpmath (tests/reference.json,
// regenerated by tests/make-reference.py).
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import * as Z from '../js/zeta.js';

const ref = JSON.parse(fs.readFileSync(new URL('./reference.json', import.meta.url)));
const err = (a, b) => Math.hypot(a[0] - b[0], a[1] - b[1]) / Math.max(1, Math.hypot(b[0], b[1]));

test('ζ(s) matches mpmath at 285 points, σ ∈ [−30, 25], |t| ≤ 1e8', () => {
  for (const [s, t, re, im] of ref.zeta) {
    const tol = Math.abs(t) > 2e7 ? 2e-6 : Math.abs(t) > 2e6 ? 5e-8 : Math.abs(t) >= 1000 ? 3e-9 : 1e-9;
    const e = err(Z.zeta(s, t), [re, im]);
    assert.ok(e < tol, `ζ(${s} + ${t}i): error ${e}`);
  }
});

test('log ζ and log ξ agree with ζ, and ξ is real on the critical line', () => {
  for (const [s, t, re, im] of ref.zeta) {
    if (Math.hypot(re, im) < 1e-6) continue;
    const l = Z.logZeta(s, t);
    assert.ok(Math.abs(l[0] - Math.log(Math.hypot(re, im))) < 1e-6, `log|ζ| at ${s}, ${t}`);
    assert.ok(Math.abs(Z.wrap(l[1] - Math.atan2(im, re))) < 1e-6, `arg ζ at ${s}, ${t}`);
  }
  for (const t of [3, 20, 50, 333.3, 5000.5]) {
    const a = Z.logXi(0.5, t)[1];
    assert.ok(Math.abs(Math.sin(a)) < 1e-7, `arg ξ(1/2 + ${t}i) = ${a}`);
    const l = Z.logXi(0.3, t), r = Z.logXi(0.7, t);
    assert.ok(Math.abs(l[0] - r[0]) < 1e-9 && Math.abs(Z.wrap(l[1] + r[1])) < 1e-7, 'ξ(s) = conj ξ(1 − s̄)');
  }
});

test('the single-precision method choices hold up in double precision', () => {
  // Riemann–Siegel from GPU.T_RS, and Euler–Maclaurin with GPU.EM_SLACK, are good to ~1e-6
  for (const [s, t, re, im] of ref.zeta) {
    const at = Math.abs(t);
    if (Z.usesRS(s, at, Z.GPU.T_RS)) {
      const v = Z.zetaRS(s, at);
      assert.ok(err([v[0], Math.sign(t || 1) * v[1]], [re, im]) < 2e-6, `RS at ${s}, ${t}`);
    } else if (s >= 0 && at < 1000) {
      const v = Z.eulerMaclaurin(s, at, Z.emTerms(s, at, Z.GPU.EM_SLACK), Z.EM_TERMS);
      assert.ok(err([v[0], Math.sign(t || 1) * v[1]], [re, im]) < 1e-7, `EM at ${s}, ${t}`);
    }
  }
});

test('Hardy Z and θ', () => {
  for (const [t, z, th] of ref.hardyZ) {
    const tol = t > 1e7 ? 2e-7 : t > 1e5 ? 1e-8 : 1e-9;
    assert.ok(Math.abs(Z.hardyZ(t) - z) < tol, `Z(${t})`);
    assert.ok(Math.abs(Z.theta(t) - th) < 1e-12 * Math.max(1, Math.abs(th)), `θ(${t})`);
  }
});

test('Gram points', () => {
  for (const [n, g] of ref.gram) assert.ok(Math.abs(Z.gramPoint(n) - g) < 1e-9 * g, `g_${n}`);
});

test('zeros on the critical line, with their indices, including Lehmer’s pair', () => {
  const known = new Map(ref.zeros);
  const zs = Z.indexedZeros(10, 40);
  assert.deepEqual(zs.map((z) => z.n), [1, 2, 3, 4, 5, 6]);
  zs.slice(0, 3).forEach((z) => assert.ok(Math.abs(z.gamma - known.get(z.n)) < 1e-10));
  const lp = Z.indexedZeros(7004, 7006.2);
  const a = lp.find((z) => z.n === 6709), b = lp.find((z) => z.n === 6710);
  assert.ok(a && b, 'both zeros of Lehmer’s pair are found');
  assert.ok(Math.abs(a.gamma - known.get(6709)) < 1e-9 && Math.abs(b.gamma - known.get(6710)) < 1e-9);
  for (const n of [1, 100, 126, 127, 1000, 10000, 100000, 1e6, 1e7]) {
    const g = Z.nthZero(n);
    assert.ok(g != null && Math.abs(g - known.get(n)) < 1e-8, `γ_${n} = ${g}`);
  }
});
